) v(num,pago,etapa,fe,rad,fac,sup,sec,notif,pres,cor,val,setval,hoja,obs) loop
  select c.id, c.etapa, (select count(*) from cc_movimientos m where m.cuenta_id=c.id) into cid, e, n
    from cc_cuentas c join cc_contratos k on k.id=c.contrato_id where k.numero_contrato=x.num and k.resolucion='0212 de 2025' and c.num_pago=x.pago;
  if cid is null then raise exception 'No existe la cuenta % pago %', x.num, x.pago; end if;
  if e<>'contratista' or n>0 then raise exception 'La cuenta % pago % ya tiene movimientos', x.num, x.pago; end if;
  fd := x.fe::date; ts := coalesce((x.fe||' 12:00:00-05')::timestamptz, now());
  update cc_cuentas set etapa=x.etapa, etapa_desde=ts,
    sp_estado='Aprobado', sp_fecha=fd-2, ct_estado='Aprobado', ct_fecha=fd-1,
    radicado=x.rad, factura=x.fac,
    sg_estado='Aprobado', sg_fecha=fd,
    sup_estado='Aprobado', sup_fecha=fd,
    secop_estado = case when upper(coalesce(x.sec,'')) like 'APRO%' then 'Aprobado' else 'Pendiente' end,
    secop_fecha  = case when upper(coalesce(x.sec,'')) like 'APRO%' then fd end,
    sg_notificado=(x.notif='t'), sg_presupuesto=(x.pres='t'), sg_correo=(x.cor='t'),
    valor = coalesce(x.setval, valor),
    observaciones = coalesce(x.obs, observaciones),
    actualizado_en=now(), actualizado_por='Migración – Excel Subgerencia'
  where id=cid;
  insert into cc_movimientos (cuenta_id,accion,etapa_origen,etapa_destino,fecha,motivo,detalle,usuario_nombre,usuario_proceso) values
    (cid,'migracion','salud_publica','contratacion',ts - interval '2 days','Migración – aprobada por Salud Pública (fecha asignada: 2 días antes de la fecha de Subgerencia)','{}'::jsonb,'Migración – Excel Subgerencia','superadmin'),
    (cid,'migracion','contratacion','subgerencia',ts - interval '1 day','Migración – aprobada por Contratación (fecha asignada: 1 día antes de la fecha de Subgerencia)','{}'::jsonb,'Migración – Excel Subgerencia','superadmin'),
